const body = $json.body;
const slots = ['10:30 AM', '11:30 AM', '02:00 PM', '04:30 PM', '06:00 PM'];

return [{
  json: {
    success: true,
    message: `Slots check for ${body.service || 'service'} on ${body.date}`,
    available_slots: slots,
    requested_date: body.date
  }
}];

const body = $json.body;
const bookingId = 'apt_' + Date.now();

return [{
  json: {
    success: true,
    message: `Appointment confirmed for ${body.customer_name} on ${body.date} at ${body.time}`,
    booking_id: bookingId,
    appointment: {
      id: bookingId,
      customer_name: body.customer_name,
      phone: body.phone,
      service: body.service,
      date: body.date,
      time: body.time,
      status: 'confirmed',
      notes: body.notes || 'Booked via Priya AI'
    },
    whatsapp_sent: true,
    google_calendar_synced: true
  }
}];

const body = $json.body;
return [{
  json: {
    success: true,
    message: `Booking ${body.booking_id || ''} has been cancelled successfully.`,
    status: 'cancelled'
  }
}];

const body = $json.body;
return [{
  json: {
    success: true,
    message: `Booking rescheduled to ${body.new_date} at ${body.new_time}.`,
    status: 'rescheduled'
  }
}];

